/** "1.234.567,50" | "1,234,567.50" | "-1234567" | "(1.000)" → rupiah bulat (dibulatkan). */
export declare function parseAmount(raw: string | null | undefined): number | null;
/** YYYY-MM-DD | DD/MM/YYYY | DD-MM-YYYY | DD/MM/YY | DD Mon YYYY → ISO. */
export declare function parseDate(raw: string | null | undefined): string | null;
